TS `senders`;\\nCREATE TABLE `senders` (\\n  `id` int(11) NOT NULL AUTO_INCREMENT,\\n  `name` varchar(255) NOT NULL,\\n  `email` varchar(255) NOT NULL,\\n  `is_default` tinyint(1) DEFAULT 0,\\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\\n  `smtp_host` varchar(255) DEFAULT NULL,\\n  `smtp_port` int(11) DEFAULT NULL,\\n  `smtp_user` varchar(255) DEFAULT NULL,\\n  `smtp_pass` varchar(255) DEFAULT NULL,\\n  `smtp_secure` varchar(50) DEFAULT \'tls\',\\n  `admin_id` int(11) DEFAULT NULL,\\n  PRIMARY KEY (`id`)\\n) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `senders` (`id`, `name`, `email`, `is_default`, `created_at`, `smtp_host`, `smtp_port`, `smtp_user`, `smtp_pass`, `smtp_secure`, `admin_id`) VALUES \\n(4, \'vnc\', \'vimal@bexcodeservices.com\', 1, \'\\\"2026-07-15T08:34:50.000Z\\\"\', \'smtp.hotmail.com\', 599, \'vimal@bexcodeservices.com\', \'password123\', \'tls\', NULL),\\n(5, \'vimal chavda\', \'chavdavimaln@gmail.com\', 0, \'\\\"2026-07-15T09:27:28.000Z\\\"\', NULL, NULL, NULL, NULL, \'tls\', NULL),\\n(7, \'aakashp\', \'info@bexcodeservices.com\', 0, \'\\\"2026-07-28T17:54:08.000Z\\\"\', \'smtp.gmail.com\', 587, \'vimal@bexcodeservices.com\', \'password123\', \'tls\', NULL);\\n\\n\",\"settings\":\"DROP TABLE IF EXISTS `settings`;\\nCREATE TABLE `settings` (\\n  `setting_key` varchar(100) NOT NULL,\\n  `setting_value` text NOT NULL,\\n  PRIMARY KEY (`setting_key`)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `settings` (`setting_key`, `setting_value`) VALUES \\n(\'company_name\', \'Bexcode\'),\\n(\'smtp_host\', \'smtp.gmail.com\'),\\n(\'smtp_pass\', \'tbwffkmwugtbaiuw\'),\\n(\'smtp_port\', \'465\'),\\n(\'smtp_user\', \'info@bexcodeservices.com\');\\n\\n\",\"admin_users\":\"DROP TABLE IF EXISTS `admin_users`;\\nCREATE TABLE `admin_users` (\\n  `id` int(11) NOT NULL AUTO_INCREMENT,\\n  `name` varchar(255) DEFAULT NULL,\\n  `email` varchar(255) NOT NU