(3, 'Whole Database Backup - 03/08/2026', '{\"subscribers\":\"DROP TABLE IF EXISTS `subscribers`;\\nCREATE TABLE `subscribers` (\\n  `id` int(11) NOT NULL AUTO_INCREMENT,\\n  `email` varchar(255) NOT NULL,\\n  `first_name` varchar(100) DEFAULT NULL,\\n  `status` enum(\'subscribed\',\'unsubscribed\',\'bounced\') DEFAULT \'subscribed\',\\n  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),\\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\\n  `admin_id` int(11) DEFAULT NULL,\\n  PRIMARY KEY (`id`),\\n  UNIQUE KEY `email` (`email`)\\n) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `subscribers` (`id`, `email`, `first_name`, `status`, `tags`, `created_at`, `admin_id`) VALUES \\n(4, \'komal@bexcodeservices.com\', \'Komal Updated\', \'subscribed\', NULL, \'\\\"2026-07-14T16:52:38.000Z\\\"\', NULL),\\n(5, \'aakash@bexcodeservices.com\', NULL, \'subscribed\', NULL, \'\\\"2026-07-14T16:52:38.000Z\\\"\', NULL),\\n(9, \'vimal@bexcodeservices.com\', \'vimal \', \'subscribed\', NULL, \'\\\"2026-07-23T09:43:14.000Z\\\"\', NULL),\\n(12, \'abc@gmail.com\', \'vimal\', \'subscribed\', NULL, \'\\\"2026-07-23T18:07:45.000Z\\\"\', NULL),\\n(13, \'text@gmail.com\', NULL, \'subscribed\', NULL, \'\\\"2026-07-23T18:07:45.000Z\\\"\', NULL),\\n(21, \'vimal@yopmail.com\', NULL, \'subscribed\', NULL, \'\\\"2026-07-24T13:11:24.000Z\\\"\', NULL),\\n(22, \'abc@yopmail.com\', NULL, \'subscribed\', NULL, \'\\\"2026-07-24T13:11:24.000Z\\\"\', NULL),\\n(23, \'vimal12@yopmail.com\', NULL, \'subscribed\', NULL, \'\\\"2026-07-24T13:14:16.000Z\\\"\', NULL),\\n(25, \'raju1@yopmail.com\', \'raju\', \'subscribed\', NULL, \'\\\"2026-07-24T13:15:58.000Z\\\"\', NULL),\\n(26, \'ramu@yopmail.com\', \'ramu\', \'subscribed\', NULL, \'\\\"2026-07-24T13:44:40.000Z\\\"\', NULL),\\n(27, \'vnc2@yopmail.com\', \'vnc 2\', \'subscribed\', NULL, \'\\\"2026-07-30T15:37:47.000Z\\\"\', 2);\\n\\n\",\"lists\":\"DROP TABLE IF EXISTS `lists`;\\nCREATE TABLE `lists` (\\n  `id` int(11) NOT NULL AUTO_INCREMENT,\\n  `name` varchar(255) NOT NULL,\\n  `description` text DEFAULT NULL,\\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\\n  `is_deleted` tinyint(1) DEFAULT 0,\\n  `admin_id` int(11) DEFAULT NULL,\\n  PRIMARY KEY (`id`)\\n) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `lists` (`id`, `name`, `description`, `created_at`, `is_deleted`, `admin_id`) VALUES \\n(1, \'Subscribers Directory\', \'Default list for campaigns\', \'\\\"2026-07-14T12:55:16.000Z\\\"\', 0, NULL),\\n(2, \'VIP Customers (Mock)\', \'VIP list\', \'\\\"2026-07-14T12:55:16.000Z\\\"\', 0, NULL),\\n(3, \'New List\', \'List of Bex\', \'\\\"2026-07-23T18:05:01.000Z\\\"\', 0, NULL),\\n(4, \'my vip list\', \'check this list\', \'\\\"2026-07-24T14:59:43.000Z\\\"\', 0, 2),\\n(5, \'fully subscriotion list\', \'check this subscription\', \'\\\"2026-07-24T15:00:25.000Z\\\"\', 0, 1),\\n(6, \'target yop\', \'description\', \'\\\"2026-07-30T13:40:08.000Z\\\"\', 1, NULL),\\n(7, \'Yop list 1\', \'hello\', \'\\\"2026-07-30T14:01:00.000Z\\\"\', 1, NULL),\\n(8, \'Target List by Yop\', \'listed yop\', \'\\\"2026-07-30T14:25:02.000Z\\\"\', 0, 2);\\n\\n\",\"campaigns\":\"DROP TABLE IF EXISTS `campaigns`;\\nCREATE TABLE `campaigns` (\\n  `id` int(11) NOT NULL AUTO_INCREMENT,\\n  `name` varchar(255) NOT NULL,\\n  `subject` varchar(255) NOT NULL,\\n  `status` enum(\'draft\',\'scheduled\',\'sending\',\'sent\',\'submitted_for_review\') DEFAULT \'draft\',\\n  `scheduled_at` datetime DEFAULT NULL,\\n  `html_content` longtext DEFAULT NULL,\\n  `scheduled_time` datetime DEFAULT NULL,\\n  `list_id` int(11) DEFAULT NULL,\\n  `target_email` text DEFAULT NULL,\\n  `sender_id` int(11) DEFAULT NULL,\\n  `is_ab_test` tinyint(1) DEFAULT 0,\\n  `variant_b_subject` varchar(255) DEFAULT NULL,\\n  `variant_b_html` longtext DEFAULT NULL,\\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),\\n  PRIMARY KEY (`id`),\\n  KEY `list_id` (`list_id`),\\n  CONSTRAINT `campaigns_ibfk_1` FOREIGN KEY (`list_id`) REFERENCES `lists` (`id`) ON DELETE SET NULL\\n) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;\\n\\nINSERT INTO `campaigns` (`id`, `name`, `subject`, `status`, `scheduled_at`, `html_content`, `scheduled_time`, `list_id`, `target_email`, `sender_id`, `is_ab_test`, `variant_b_subject`, `variant_b_html`, `created_at`, `updated_at`) VALUES \\n(6, \'New Compaign\', \'Subject  Variant A\', \'sent\', NULL, \'<!DOCTYPE HTML PUBLIC \\\"-//W3C//DTD XHTML 1.0 Transitional //EN\\\" \\\"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\\\">\\n<html xmlns=\\\"http://www.w3.org/1999/xhtml\\\" xmlns:v=\\\"urn:schemas-microsoft-com:vml\\\" xmlns:o=\\\"urn:schemas-microsoft-com:office:office\\\">\\n<head>\\n<!--[if gte mso 9]>\\n<xml>\\n  <o:OfficeDocumentSettings>\\n    <o:AllowPNG/>\\n    <o:PixelsPerInch>96</o:PixelsPerInch>\\n  </o:OfficeDocumentSettings>\\n</xml>\\n<![endif]-->\\n  <meta http-equiv=\\\"Content-Type\\\" content=\\\"text/html; charset=UTF-8\\\">\\n  <meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n  <meta name=\\\"x-apple-disable-message-reformatting\\\">\\n  <!--[if !mso]><!--><meta http-equiv=\\\"X-UA-Compatible\\\" content=\\\"IE=edge\\\"><!--<![endif]-->\\n  \\n  \\n    <style type=\\\"text/css\\\">\\n      \\n      @media only screen and (min-width: 520px) {\\n        .u-row {\\n          width: 500px !important;\\n        }\\n\\n        .u-row .u-col {\\n          vertical-align: top;\\n        }\\n\\n        \\n            .u-row .u-col-100 {\\n              width: 500px !important;\\n            }\\n          \\n      }\\n\\n      @media only screen and (max-width: 520px) {\\n        .u-row-container {\\n          max-width: 100% !important;\\n          pa